import{_ as t,o,c as a,ah as r}from"./chunks/framework.Sdx4l2LO.js";const p=JSON.parse('{"title":"Extended Feature Evaluation Pipeline (Pipeline A)","description":"","frontmatter":{},"headers":[],"relativePath":"EXTENDED_FEATURE_EVAL.md","filePath":"EXTENDED_FEATURE_EVAL.md","lastUpdated":1774803703000}'),i={name:"EXTENDED_FEATURE_EVAL.md"};function l(s,e,n,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="extended-feature-evaluation-pipeline-pipeline-a" tabindex="-1">Extended Feature Evaluation Pipeline (Pipeline A) <a class="header-anchor" href="#extended-feature-evaluation-pipeline-pipeline-a" aria-label="Permalink to &quot;Extended Feature Evaluation Pipeline (Pipeline A)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <code>/eval-game-features</code> command extends the existing <code>/prove-features</code> pipeline to validate <strong>5 additional runtime capabilities</strong> using MCP tools and VLM screenshot analysis.</p><p><strong>Core 3 features</strong> (validated by <code>/prove-features</code>):</p><ul><li>Mods button visible</li><li>F9 debug overlay</li><li>F10 mod menu</li></ul><p><strong>Extended 5 features</strong> (validated by <code>/eval-game-features</code>):</p><ul><li><strong>A-2</strong>: Stat override (HP=999 via <code>game_apply_override</code>)</li><li><strong>A-3</strong>: Hot reload (YAML change picked up without restart via <code>game_reload_packs</code>)</li><li><strong>A-4</strong>: Economy pack loaded + resources queryable</li><li><strong>A-5</strong>: Scenario pack loaded + scenario system active</li><li><strong>A-6</strong>: Asset swap (clone trooper visual model visible)</li></ul><h2 id="file-structure" tabindex="-1">File Structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to &quot;File Structure&quot;">​</a></h2><h3 id="command-definition" tabindex="-1">Command Definition <a class="header-anchor" href="#command-definition" aria-label="Permalink to &quot;Command Definition&quot;">​</a></h3><ul><li><strong><code>.claude/commands/eval-game-features.md</code></strong> — Complete orchestration guide for Claude <ul><li>6 main steps (game bridge check, A-2, A-3, A-4, A-5, A-6)</li><li>Explicit MCP tool calls with parameter names and types</li><li>VLM prompts for each feature screenshot</li><li>JSON report structure and bundling instructions</li><li>Error handling policy (continue on individual failures, aggregate results)</li></ul></li></ul><h3 id="helper-script" tabindex="-1">Helper Script <a class="header-anchor" href="#helper-script" aria-label="Permalink to &quot;Helper Script&quot;">​</a></h3><ul><li><strong><code>scripts/game/eval-game-features.ps1</code></strong> — Pre-flight checks <ul><li>Verifies MCP server health on <code>http://127.0.0.1:8765</code></li><li>Builds test projects to ensure no compilation errors</li><li>Prepares output directories (<code>$env:TEMP\\DINOForge\\capture</code> and <code>docs/proof-of-features/</code>)</li><li>Provides instructions for users</li></ul></li></ul><h2 id="mcp-tools-used" tabindex="-1">MCP Tools Used <a class="header-anchor" href="#mcp-tools-used" aria-label="Permalink to &quot;MCP Tools Used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Feature</th><th>Purpose</th></tr></thead><tbody><tr><td><code>game_status</code></td><td>Baseline</td><td>Verify game is running, entity count &gt; 0</td></tr><tr><td><code>game_apply_override</code></td><td>A-2</td><td>Apply stat override (HP=999)</td></tr><tr><td><code>game_get_stat</code></td><td>A-2</td><td>Query stat value to verify override applied</td></tr><tr><td><code>game_input</code></td><td>A-2</td><td>Press F9 to open debug overlay for screenshot</td></tr><tr><td><code>game_screenshot</code></td><td>All</td><td>Capture current game window (GDI, no compression)</td></tr><tr><td><code>game_analyze_screen</code></td><td>All</td><td>VLM analysis of screenshot with custom prompt</td></tr><tr><td><code>game_reload_packs</code></td><td>A-3</td><td>Trigger hot reload (writes HMR signal file)</td></tr><tr><td><code>log_tail</code></td><td>A-3, A-5</td><td>Tail BepInEx log to find reload/scenario evidence</td></tr><tr><td><code>game_get_resources</code></td><td>A-4</td><td>Query current economy resources (gold, food, etc.)</td></tr><tr><td><code>game_dump_state</code></td><td>A-6</td><td>Dump unit entities to find clone trooper models</td></tr><tr><td><code>log_swap_status</code></td><td>A-6</td><td>Query asset swap completion count</td></tr></tbody></table><h2 id="evaluation-flow" tabindex="-1">Evaluation Flow <a class="header-anchor" href="#evaluation-flow" aria-label="Permalink to &quot;Evaluation Flow&quot;">​</a></h2><h3 id="pre-requisites" tabindex="-1">Pre-requisites <a class="header-anchor" href="#pre-requisites" aria-label="Permalink to &quot;Pre-requisites&quot;">​</a></h3><ol><li>Game is running with DINOForge Runtime loaded</li><li>MCP server is running on <code>http://127.0.0.1:8765</code></li><li>(Optional) Run <code>/prove-features</code> first to ensure stable boot</li></ol><h3 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h3><ol><li><strong>Step 1</strong>: Call <code>game_status</code> — verify game is ready (running, entity count &gt; 0)</li><li><strong>Feature A-2</strong>: Apply override, query stat, screenshot F9 overlay, VLM validate</li><li><strong>Feature A-3</strong>: Trigger reload, tail logs for &quot;reload&quot; keyword, screenshot, VLM validate game stability</li><li><strong>Feature A-4</strong>: Check economy pack loaded, query resources, screenshot, VLM validate resource HUD</li><li><strong>Feature A-5</strong>: Check scenario pack loaded, tail logs for &quot;ScenarioRunner&quot;, screenshot, VLM validate gameplay</li><li><strong>Feature A-6</strong>: Check swap status, dump entities for clone troopers, screenshot, VLM detect Star Wars units</li><li><strong>Bundling</strong>: Aggregate all results into <code>validate_extended_report.json</code>, copy artifacts to <code>docs/proof-of-features/extended_&lt;timestamp&gt;/</code></li></ol><h3 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h3><ul><li><strong><code>validate_extended_report.json</code></strong> — Structured results: stat values, pack loaded flags, VLM confirmations, timestamps</li><li><strong>5 screenshots</strong> — One per feature (PNG, GDI-captured, live game window)</li><li><strong><code>EXTENDED_EVAL_REPORT.md</code></strong> — Human-readable summary with feature validation table</li></ul><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><ul><li><strong>If game not running</strong>: STOP and ask user to <code>/launch-game</code> or <code>/prove-features</code></li><li><strong>If MCP server unreachable</strong>: STOP and provide instructions to start MCP server</li><li><strong>If individual feature fails</strong>: Log failure, but CONTINUE to next feature (do not stop pipeline)</li><li><strong>Overall result</strong>: If &gt;= 3/5 features confirmed, mark as &quot;PASS&quot;; if &lt; 3, mark as &quot;PARTIAL PASS&quot;</li></ul><h2 id="vlm-model-selection" tabindex="-1">VLM Model Selection <a class="header-anchor" href="#vlm-model-selection" aria-label="Permalink to &quot;VLM Model Selection&quot;">​</a></h2><p>For <code>game_analyze_screen</code> calls:</p><ol><li><strong>Claude Opus</strong> (if available and budget allows)</li><li><strong>Claude Sonnet 4</strong> (preferred balance of capability and cost)</li><li><strong>Claude Haiku</strong> (fallback, fast mode OK)</li></ol><p>Each VLM call receives:</p><ul><li>Live GDI screenshot (no compression, captured while game is running)</li><li>Custom prompt asking about specific visual feature (HP=999, resource HUD, clone trooper, etc.)</li><li>Returns text analysis (what it sees in the screenshot)</li></ul><h2 id="integration-with-existing-commands" tabindex="-1">Integration with Existing Commands <a class="header-anchor" href="#integration-with-existing-commands" aria-label="Permalink to &quot;Integration with Existing Commands&quot;">​</a></h2><ul><li><strong><code>/prove-features</code></strong> — Validates core 3 features (video-based, Remotion renders)</li><li><strong><code>/eval-game-features</code></strong> — Validates extended 5 features (MCP-based, screenshot-based)</li><li><strong><code>/eval-all</code></strong> — Could orchestrate both <code>/prove-features</code> and <code>/eval-game-features</code> in sequence</li></ul><h2 id="future-extensions" tabindex="-1">Future Extensions <a class="header-anchor" href="#future-extensions" aria-label="Permalink to &quot;Future Extensions&quot;">​</a></h2><p>Potential additions to the extended pipeline:</p><ul><li><strong>A-7</strong>: Mod compatibility check (pack conflict detection via registry)</li><li><strong>A-8</strong>: Performance profiling (entity count, frame time via game telemetry)</li><li><strong>A-9</strong>: Save/load mechanics (game state persistence)</li><li><strong>A-10</strong>: Network multiplayer (if applicable)</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Command file: <code>.claude/commands/eval-game-features.md</code></li><li>Helper script: <code>scripts/game/eval-game-features.ps1</code></li><li>MCP tool catalog: <code>CLAUDE.md</code> (Game Automation section)</li><li>Existing pipeline: <code>.claude/commands/prove-features.md</code></li></ul>',35)])])}const m=t(i,[["render",l]]);export{p as __pageData,m as default};
